function validate([n, k]) {
  if (!Number.isInteger(n) || n < 1 || n > 9) return 'n is a whole number from 1 to 9.';
  let total = 1;
  for (let i = 2; i <= n; i++) total *= i;
  if (!Number.isInteger(k) || k < 1 || k > total) return 'k is a whole number from 1 to n!.';
  return null;
}

