function getPermutation(n, k) {
  const digits = [];
  const factorial = [1];
  for (let i = 1; i <= n; i++) {
    digits.push(i);
    factorial.push(factorial[i - 1] * i);
  }
  let rank = k - 1;
  let result = '';
  for (let remaining = n; remaining >= 1; remaining--) {
    const blockSize = factorial[remaining - 1];
    const index = Math.floor(rank / blockSize);
    result += digits[index];
    digits.splice(index, 1);
    rank %= blockSize;
  }
  return result;
}

