function getPermutation(n, k) {
  // List permutations in dictionary order by depth-first search and stop at the k-th.
  const used = new Array(n + 1).fill(false);
  let count = 0;
  let answer = null;
  const build = (prefix) => {
    if (answer !== null) return;
    if (prefix.length === n) {
      count++;
      if (count === k) answer = prefix;
      return;
    }
    for (let d = 1; d <= n; d++) {
      if (used[d]) continue;
      used[d] = true;
      build(prefix + d);
      used[d] = false;
    }
  };
  build('');
  return answer;
}

