function generate(rand, size) {
  const n = size === 'large' ? 9 : 1 + Math.floor(rand() * 6);
  let total = 1;
  for (let i = 2; i <= n; i++) total *= i;
  const roll = rand();
  const k = roll < 0.15 ? 1 : roll < 0.3 ? total : 1 + Math.floor(rand() * total);
  return [n, k];
}
